SELECT MIN(h.grade) AS lowest_grade
FROM Highschooler h
WHERE NOT EXISTS (
  SELECT 1 FROM Friend f WHERE f.student_id = h.ID
)
AND NOT EXISTS (
  SELECT 1 FROM Friend f WHERE f.friend_id = h.ID
);

